self.onInit = function () {
    var TEMPLATE_NAME = 'Minta';
    // system attributes that must not be copied
    var SKIP_KEYS = ['active', 'lastActivityTime', 'lastConnectTime',
                     'lastDisconnectTime', 'inactivityAlarmTime'];

    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var macBox = $('.dv-mac');
    var nameBox = $('.dv-name');
    var btn = $('.dv-create');
    var msg = $('.dv-msg');
    var result = $('.dv-result');
    var tokenBox = $('.dv-token');
    var copyBtn = $('.dv-copy');

    function show(text, ok) {
        msg.textContent = text;
        msg.className = 'dv-msg ' + (ok ? 'dv-ok' : 'dv-err');
    }

    function errText(e) {
        if (!e) { return 'Ismeretlen hiba'; }
        var m = (e.error && e.error.message) ? e.error.message : '';
        return (e.status ? e.status + ' ' : '') + (e.url ? '[' + e.url + '] ' : '') + (m || 'Ismeretlen hiba');
    }

    // last 6 hex characters of a MAC address (full address or just the end of it)
    function macSuffix(v) {
        var clean = String(v).replace(/[\s:.\-]/g, '');
        if (!/^[0-9a-fA-F]{6,12}$/.test(clean)) { return null; }
        return clean.slice(-6).toUpperCase();
    }

    function copyText(text, done) {
        function fallback() {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.cssText = 'position:fixed;left:-1000px;top:0;';
            document.body.appendChild(ta);
            ta.select();
            try { document.execCommand('copy'); } catch (e) {}
            document.body.removeChild(ta);
            done();
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done, fallback);
        } else {
            fallback();
        }
    }

    // the template device ("Minta")
    function loadTemplate(cb) {
        http.get('/api/tenant/devices?deviceName=' + encodeURIComponent(TEMPLATE_NAME)).subscribe(
            function (dev) { cb(null, dev); },
            function (e) { cb('a(z) "' + TEMPLATE_NAME + '" sablon gép nem található: ' + errText(e)); }
        );
    }

    // body of the new device: settings of the template, no customer, label = name
    function bodyFrom(tpl, name) {
        var b = { name: name, label: name, type: tpl.type };
        ['deviceProfileId', 'additionalInfo', 'deviceData', 'firmwareId', 'softwareId'].forEach(function (k) {
            if (tpl[k] !== undefined && tpl[k] !== null) { b[k] = JSON.parse(JSON.stringify(tpl[k])); }
        });
        return b;
    }

    // copies the attributes of one scope from the template to the new device
    function copyAttributes(fromId, toId, scope, cb) {
        http.get('/api/plugins/telemetry/DEVICE/' + fromId + '/values/attributes/' + scope).subscribe(
            function (arr) {
                var body = {}, n = 0;
                (arr || []).forEach(function (a) {
                    if (SKIP_KEYS.indexOf(a.key) < 0) { body[a.key] = a.value; n++; }
                });
                if (!n) { cb(null, 0); return; }
                http.post('/api/plugins/telemetry/DEVICE/' + toId + '/attributes/' + scope, body).subscribe(
                    function () { cb(null, n); },
                    function (e) { cb(errText(e)); }
                );
            },
            function (e) { cb(errText(e)); }
        );
    }

    macBox.addEventListener('input', function () {
        result.style.display = 'none';
        msg.textContent = '';
        nameBox.value = macSuffix(macBox.value) || '';
    });

    copyBtn.addEventListener('click', function () {
        copyText(tokenBox.textContent, function () {
            copyBtn.textContent = 'Másolva!';
            setTimeout(function () { copyBtn.textContent = 'Másolás'; }, 1500);
        });
    });

    btn.addEventListener('click', function () {
        var name = macSuffix(macBox.value);
        if (!name) { show('Érvénytelen MAC-cím: legalább 6 hexadecimális karakter kell.', false); return; }

        btn.disabled = true;
        result.style.display = 'none';
        show('Létrehozás...', true);

        // 0) the template must exist before anything is created
        loadTemplate(function (terr, tpl) {
            if (terr) { show('Hiba: ' + terr, false); btn.disabled = false; return; }

            // 1) device with the settings of the template (owned by you, no customer)
            http.post('/api/device', bodyFrom(tpl, name)).subscribe(
                function (dev) {
                    var did = dev.id.id;
                    var notes = [];

                    // 2) attributes of the template (server, then shared)
                    copyAttributes(tpl.id.id, did, 'SERVER_SCOPE', function (e1, n1) {
                        if (e1) { notes.push('szerver attribútumok: ' + e1); }
                        copyAttributes(tpl.id.id, did, 'SHARED_SCOPE', function (e2, n2) {
                            if (e2) { notes.push('megosztott attribútumok: ' + e2); }

                            // 3) the new device's own token
                            http.get('/api/device/' + did + '/credentials').subscribe(
                                function (cred) {
                                    tokenBox.textContent = cred.credentialsId || '';
                                    result.style.display = 'block';
                                    if (notes.length) {
                                        show(name + ' létrejött, de: ' + notes.join(' | '), false);
                                    } else {
                                        show('Kész: ' + name + ' létrejött (nincs ügyfélhez rendelve); átmásolva: ' +
                                             (n1 || 0) + ' szerver és ' + (n2 || 0) + ' megosztott attribútum.', true);
                                    }
                                    btn.disabled = false;
                                },
                                function (e) {
                                    show(name + ' létrejött, de a token nem olvasható: ' + errText(e), false);
                                    btn.disabled = false;
                                }
                            );
                        });
                    });
                },
                function (e) {
                    show('Gép hiba: ' + errText(e), false);
                    btn.disabled = false;
                }
            );
        });
    });
};

self.onDestroy = function () {};

